export const API_VERSION = 'v1';

/**
 * AUTH. The app calls POST /v1/devices once on first launch and stores the
 * returned deviceId + token. Every other request that concerns a device sends
 * `Authorization: Bearer <token>`; the server derives the device from the
 * token. `deviceId` is no longer accepted as a query/body credential.
 * Catalog endpoints (search, suggest, home, products, lookup) also work with
 * no token (anonymous, unpersonalized). Profile, events, alerts and ask need
 * a token and return 401 without one.
 *
 * SHOPPER CONTEXT. Catalog endpoints accept optional query params:
 *   zip=12345                      -> fills Offer.estimatedTax
 *   memberships=costco,samsclub    -> sets Offer.eligible ("" = holds none)
 * Omit `memberships` entirely when the user has not answered.
 *   storeIds=wm-123,kr-456         -> price from these store locations
 * When storeIds is omitted but zip is given, the server uses the nearest
 * store of each retailer. Without either, prices are national/demo.
 */
export interface RegisterDeviceResponse {
  deviceId: string;
  token: string;
}

export type RetailerId =
  | 'amazon'
  | 'walmart'
  | 'samsclub'
  | 'target'
  | 'costco'
  | 'bestbuy'
  | 'kroger';

/**
 * How an offer's price was obtained.
 * 'live' = from a retailer API; 'demo' = synthetic mock data;
 * 'link_only' = no price available, the offer is just a "check price" link
 * (price fields are 0 and must not be shown or ranked as cheapest).
 */
export type PriceSource = 'live' | 'demo' | 'link_only';

export interface Retailer {
  id: RetailerId;
  name: string;
  /** Brand hex color, used for the retailer chip. */
  color: string;
  /** True when buying generally needs a paid membership (Sam's Club, Costco). */
  membershipRequired: boolean;
}

export type SizeUnit = 'oz' | 'lb' | 'fl_oz' | 'gal' | 'ct' | 'each';

/** Package size, e.g. { amount: 5, unit: 'lb' }. */
export interface PackageSize {
  amount: number;
  unit: SizeUnit;
}

/** A physical store location. Grocery prices are per store. */
export interface Store {
  id: string;
  retailerId: RetailerId;
  name: string;
  address: string;
  distanceMiles: number;
}

export interface Offer {
  id: string;
  productId: string;
  retailerId: RetailerId;
  /** Item price in USD, before shipping. */
  price: number;
  /** Strikethrough/list price if the retailer shows one. */
  listPrice: number | null;
  /** Shipping cost in USD. 0 = free shipping. null = unknown. */
  shipping: number | null;
  /** price + (shipping ?? 0). */
  totalPrice: number;
  /** Estimated sales tax in USD for the request's zip, null when no zip given. */
  estimatedTax: number | null;
  /** totalPrice + (estimatedTax ?? 0). "Cheapest" is computed on this. */
  landedPrice: number;
  /**
   * False when the offer needs a membership the user said they do not hold.
   * Always true when the request did not state memberships (unknown).
   */
  eligible: boolean;
  inStock: boolean;
  membershipRequired: boolean;
  /** Retailer-specific rating 0-5 and review count, when available. */
  rating: number | null;
  reviewCount: number | null;
  /** e.g. "Tomorrow", "2-day", "Pickup today". */
  delivery: string | null;
  /** Outbound link to the retailer product page. */
  url: string;
  /** ISO timestamp of when this price was observed. */
  observedAt: string;
  priceSource: PriceSource;
  /**
   * 'exact' = the same item (same GTIN). 'equivalent' = a comparable item at
   * this store, typically its store brand; the UI must label it and show
   * offerTitle. Equivalent offers are compared on unitPrice, not shelf price.
   */
  matchType: 'exact' | 'equivalent';
  /** The item's actual name at this store when matchType is 'equivalent'. */
  offerTitle: string | null;
  /** Size of the item this offer sells (may differ for equivalents). */
  size: PackageSize | null;
  /** price / size in a normalized unit, e.g. 0.08. null when size unknown. */
  unitPrice: number | null;
  /** e.g. "per oz", "per lb", "per fl oz", "each". */
  unitLabel: string | null;
  /** Store location this price is from, null for online/national prices. */
  storeId: string | null;
}

export interface Product {
  id: string;
  title: string;
  brand: string;
  category: string;
  /** Package size of the reference item, null when not applicable. */
  size: PackageSize | null;
  /** True for a retailer's own label (Great Value, Kroger, Kirkland...). */
  isStoreBrand: boolean;
  /** May be null: the app must render a designed placeholder tile. */
  imageUrl: string | null;
  gtin: string | null;
  /** Short key facts, e.g. ["6-cup", "Fuzzy logic", "Keep warm"]. */
  highlights: string[];
  /** Review-count-weighted average rating across offers. */
  rating: number | null;
  reviewCount: number;
  /** Sorted for this user (personalized) — index 0 is the recommended offer. */
  offers: Offer[];
  /** Offer with the lowest landedPrice among in-stock, eligible offers. */
  cheapestOfferId: string | null;
  /** offers[0].id — may differ from cheapest when personalization applies. */
  recommendedOfferId: string | null;
  /** Human-readable reason when recommended != cheapest, else null. */
  recommendationReason: string | null;
  /** Highest minus lowest landedPrice among in-stock, eligible offers. */
  maxSavings: number;
}

export interface PricePoint {
  /** ISO date (YYYY-MM-DD). */
  date: string;
  retailerId: RetailerId;
  price: number;
}

export interface ProductDetail extends Product {
  description: string;
  priceHistory: PricePoint[];
  /** Short review-backed pros/cons. */
  reviewSummary: { pros: string[]; cons: string[] } | null;
}

